:root {
  --bg: #1a1c2c;
  --surface: #2b3042;
  --text: #f4f4f6;
  --accent: #f28c5b;
  --shadow: #0f0f17;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: var(--bg);
  background-image:
    linear-gradient(rgba(244,244,246,0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(244,244,246,0.08) 1px, transparent 1px);
  background-size: 20px 20px;
  font-family: 'Segoe UI', Arial, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.timer-card {
  width: 100%;
  max-width: 480px;
  background: var(--surface);
  border: 4px solid var(--shadow);
  border-radius: 8px;
  box-shadow: 8px 8px 0 var(--shadow);
  padding: 32px 24px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 24px;
}
h1 {
  margin: 0;
  font-size: 1.75rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--shadow);
}
.mode-label {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 600;
  background: var(--surface);
  display: inline-block;
  align-self: center;
  padding: 8px 20px;
  border: 2px solid var(--shadow);
  border-radius: 999px;
  box-shadow: 2px 2px 0 var(--shadow);
}
.countdown {
  font-family: 'Courier New', Courier, monospace;
  font-size: clamp(3rem, 15vw, 5.5rem);
  font-weight: 700;
  letter-spacing: 4px;
  background: var(--shadow);
  color: var(--text);
  padding: 16px 8px;
  border: 4px solid var(--shadow);
  border-radius: 8px;
  box-shadow: inset 0 0 0 2px var(--surface);
  word-break: break-word;
}
.controls {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12px;
}
button {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text);
  background: var(--accent);
  border: 3px solid var(--shadow);
  border-radius: 8px;
  padding: 12px 22px;
  cursor: pointer;
  box-shadow: 4px 4px 0 var(--shadow);
  transition: transform 0.05s ease, box-shadow 0.05s ease, filter 0.2s ease;
  min-height: 48px;
  min-width: 100px;
}
button:hover:not(:disabled) {
  filter: brightness(1.1);
}
button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
  filter: brightness(1.1);
}
button:active:not(:disabled) {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 var(--shadow);
}
button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  box-shadow: 2px 2px 0 var(--shadow);
  transform: none;
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
@media (max-width: 420px) {
  .timer-card {
    padding: 24px 16px;
    gap: 18px;
  }
  .controls {
    gap: 10px;
  }
  button {
    padding: 10px 14px;
    min-width: 80px;
    font-size: 1rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const WORK_DURATION = 25 * 60;
  const BREAK_DURATION = 5 * 60;
  const countdownEl = document.getElementById('countdown');
  const modeLabelEl = document.getElementById('mode-label');
  const startBtn = document.getElementById('start-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const resetBtn = document.getElementById('reset-btn');
  const statusEl = document.getElementById('timer-status');

  let mode = 'work';
  let remainingSeconds = WORK_DURATION;
  let timerId = null;
  let isRunning = false;
  let lastTick = 0;

  const durationForMode = (m) => m === 'work' ? WORK_DURATION : BREAK_DURATION;
  const otherMode = (m) => m === 'work' ? 'break' : 'work';

  function formatTime(totalSeconds) {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  }

  function updateDisplay() {
    countdownEl.textContent = formatTime(remainingSeconds);
    modeLabelEl.textContent = mode === 'work' ? 'Work Mode' : 'Break Mode';
  }

  function updateControls() {
    startBtn.disabled = isRunning;
    pauseBtn.disabled = !isRunning;
  }

  function setStatus(message) {
    statusEl.textContent = message;
  }

  function startTimer() {
    if (isRunning) return;
    isRunning = true;
    lastTick = Date.now();
    timerId = setInterval(tick, 250);
    updateControls();
    setStatus(`${mode === 'work' ? 'Work' : 'Break'} timer running`);
  }

  function pauseTimer() {
    if (!isRunning) return;
    isRunning = false;
    clearInterval(timerId);
    timerId = null;
    updateControls();
    setStatus(`${mode === 'work' ? 'Work' : 'Break'} timer paused`);
  }

  function resetTimer() {
    pauseTimer();
    remainingSeconds = durationForMode(mode);
    updateDisplay();
    setStatus(`${mode === 'work' ? 'Work' : 'Break'} timer reset`);
  }

  function tick() {
    const now = Date.now();
    const delta = Math.floor((now - lastTick) / 1000);
    if (delta < 1) return;
    lastTick += delta * 1000;
    remainingSeconds = Math.max(0, remainingSeconds - delta);
    updateDisplay();
    if (remainingSeconds <= 0) {
      clearInterval(timerId);
      timerId = null;
      isRunning = false;
      mode = otherMode(mode);
      remainingSeconds = durationForMode(mode);
      updateDisplay();
      updateControls();
      setStatus(`${mode === 'work' ? 'Work' : 'Break'} timer ready`);
    }
  }

  startBtn.addEventListener('click', startTimer);
  pauseBtn.addEventListener('click', pauseTimer);
  resetBtn.addEventListener('click', resetTimer);

  updateDisplay();
  updateControls();
  setStatus('Work timer ready');
});
